        require(address(this).balance >= amount);

        // Record whether this test contract is the owner of c.
        bool isOwner = (address(this) == c.owner());

        // Seed c with some Ether so that withdrawAll has a non-zero balance to send.
        (bool seedOk, ) = address(c).call{value: amount}("");

        uint cBalBefore = address(c).balance;
        uint selfBalBefore = address(this).balance;

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (isOwner && !reverted) {
            assert(address(c).balance == 0);
            assert(address(this).balance == selfBalBefore + cBalBefore);
        } else if (isOwner && reverted) {
            assert(address(c).balance == cBalBefore);
            assert(address(this).balance == selfBalBefore);
        } else {
            assert(reverted);
            assert(address(c).balance == cBalBefore);
            assert(address(this).balance == selfBalBefore);
        }
    }

    receive() external payable {}
}

