    constructor(C _c) {
        c = _c;
    }

    function run(address target, uint value) public payable {
        require(target != address(0));
        require(target != address(c));
        require(target != address(this));
        require(value <= address(this).balance);

        if (value > 0) {
            (bool ok, ) = address(c).call{value: value}("");
            require(ok);
        }

        uint balBefore = address(c).balance;
        uint targetBalBefore = target.balance;
        uint countBefore = c.depositsCount();

        bool reverted;
        try c.sendMoney(target, value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;
        uint targetBalAfter = target.balance;
        uint countAfter = c.depositsCount();
        bool hadEnough = balBefore >= value;

        assert(!reverted && countAfter == countBefore && (hadEnough ? (balAfter + value == balBefore && targetBalAfter == targetBalBefore + value) : (balAfter == balBefore && targetBalAfter == targetBalBefore)));
    }

    receive() external payable {}
}

