contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // Make the test contract the owner by calling from this contract.
        // Since run is called on InvMutTest, msg.sender for c.withdrawAll() will be address(this),
        // which matches c.owner() because the test contract deployed c.

        // Fund c with Ether so that withdrawAll has something to transfer.
        // Use a top-level call to the receive function via a low-level call,
        // but we must avoid nesting state-changing calls in assertions/conditions.
        // We can send Ether directly to c as a top-level call.
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent, "funding failed");

        uint balanceBefore = address(c).balance;
        uint testBalanceBefore = address(this).balance;

        // Drive the public entry withdrawAll.
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balanceAfter = address(c).balance;
        uint testBalanceAfter = address(this).balance;

        // General rule: for the owner, withdrawAll does not revert and transfers the entire balance to the caller.
        assert(
            !reverted &&
            balanceBefore > 0 &&
            balanceAfter == 0 &&
            testBalanceAfter == testBalanceBefore + balanceBefore
        );
    }

    receive() external payable {}
}

